import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.DgC0bfPP.js";const g=JSON.parse('{"title":"快速开始指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/quickstart.md","filePath":"zh/quickstart.md"}'),s={name:"zh/quickstart.md"};function r(o,a,n,h,d,p){return i(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="快速开始指南" tabindex="-1">快速开始指南 <a class="header-anchor" href="#快速开始指南" aria-label="Permalink to &quot;快速开始指南&quot;">​</a></h1><p>欢迎使用 <strong>CoWatcher</strong>！本指南将带你在 3 分钟内完成浏览器扩展的安装、配置并开始在流媒体平台畅享 AI 双语字幕。</p><hr><h2 id="_1-安装与载入扩展" tabindex="-1">1. 安装与载入扩展 <a class="header-anchor" href="#_1-安装与载入扩展" aria-label="Permalink to &quot;1. 安装与载入扩展&quot;">​</a></h2><h3 id="方式-a-google-chrome-edge-brave-等-chromium-内核浏览器" tabindex="-1">方式 A：Google Chrome / Edge / Brave 等 Chromium 内核浏览器 <a class="header-anchor" href="#方式-a-google-chrome-edge-brave-等-chromium-内核浏览器" aria-label="Permalink to &quot;方式 A：Google Chrome / Edge / Brave 等 Chromium 内核浏览器&quot;">​</a></h3><ol><li>从 GitHub 仓库获取最新打包文件或自行编译：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/SFBB/NetflixCoWatcher.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cowatcher-extension-public</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:chrome</span></span></code></pre></div></li><li>打开浏览器，在地址栏输入 <code>chrome://extensions/</code> 并回车。</li><li>打开右上角的 <strong>开发者模式 (Developer mode)</strong> 开关。</li><li>点击左上角的 <strong>加载已解压的扩展程序 (Load unpacked)</strong> 按钮。</li><li>选择项目目录下的 <code>dist/</code> 文件夹。</li></ol><h3 id="方式-b-mozilla-firefox" tabindex="-1">方式 B：Mozilla Firefox <a class="header-anchor" href="#方式-b-mozilla-firefox" aria-label="Permalink to &quot;方式 B：Mozilla Firefox&quot;">​</a></h3><ol><li>编译 Firefox 专属版本：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:firefox</span></span></code></pre></div></li><li>打开 Firefox，在地址栏输入 <code>about:debugging#/runtime/this-firefox</code>。</li><li>点击 <strong>临时载入附加组件 (Load Temporary Add-on...)</strong>。</li><li>选择项目目录下的 <code>dist-firefox/manifest.json</code> 文件。</li></ol><hr><h2 id="_2-首次启动与-ai-服务连接" tabindex="-1">2. 首次启动与 AI 服务连接 <a class="header-anchor" href="#_2-首次启动与-ai-服务连接" aria-label="Permalink to &quot;2. 首次启动与 AI 服务连接&quot;">​</a></h2><p>安装完成后，点击浏览器工具栏右上角的 <strong>CoWatcher</strong> 图标打开面板：</p><ol><li><strong>选择 AI 提供商</strong>： <ul><li>如果你有独立显卡（NVIDIA / Apple Silicon）并追求 <strong>完全免费与绝对隐私</strong>，推荐选择 <strong>Ollama</strong>。详见 <a href="/NetflixCoWatcher/zh/providers/ollama.html">Ollama 配置指南</a>。</li><li>如果你想使用目前最强的云端大模型（DeepSeek V3、Gemini 2.5 Flash、Claude 等），推荐选择 <strong>OpenRouter</strong>。详见 <a href="/NetflixCoWatcher/zh/providers/openrouter.html">OpenRouter 配置指南</a>。</li></ul></li><li><strong>设置目标翻译语言</strong>： <ul><li>在面板中将 <strong>Target Language</strong> 设置为你偏好的母语（如 <code>Chinese (Simplified)</code> 简体中文）。</li></ul></li><li><strong>确认连接指示灯</strong>： <ul><li>面板右上角的状态卡片显示 🟢 <strong>Connected</strong> 时，表示模型与服务正常连接。</li></ul></li></ol><hr><h2 id="_3-在流媒体中开启双语字幕" tabindex="-1">3. 在流媒体中开启双语字幕 <a class="header-anchor" href="#_3-在流媒体中开启双语字幕" aria-label="Permalink to &quot;3. 在流媒体中开启双语字幕&quot;">​</a></h2><p>打开任意支持的视频流媒体网站：</p><ul><li><a href="https://www.netflix.com/" target="_blank" rel="noreferrer">Netflix (网飞)</a></li><li><a href="https://tver.jp/" target="_blank" rel="noreferrer">TVer (日本电视/日剧)</a></li><li><a href="https://www.youtube.com/" target="_blank" rel="noreferrer">YouTube</a></li></ul><h3 id="快捷控制方式" tabindex="-1">快捷控制方式 <a class="header-anchor" href="#快捷控制方式" aria-label="Permalink to &quot;快捷控制方式&quot;">​</a></h3><ul><li><strong>全局快捷键</strong>：在播放器页面任意时刻按下 <strong><code>Alt + T</code></strong>，即可一键开启或关闭 AI 双语字幕。</li><li><strong>播放器控制按钮</strong>：播放器工具栏旁会自动注入 CoWatcher 的专属控制按钮，点击即可实时呼出快速控制浮层。</li><li><strong>全屏自适应</strong>：进入全屏播放后，字幕会自动调整缩放比例并居中挂载，完全不遮挡原生播放进度条。</li></ul><hr><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>深入了解 <a href="/NetflixCoWatcher/zh/guide/popup.html">弹窗面板与快捷键指南</a></li><li>查看流媒体专属调优：<a href="/NetflixCoWatcher/zh/platforms/netflix.html">Netflix 说明</a> · <a href="/NetflixCoWatcher/zh/platforms/tver.html">TVer 说明</a> · <a href="/NetflixCoWatcher/zh/platforms/youtube.html">YouTube 说明</a></li><li>探索 <a href="/NetflixCoWatcher/zh/advanced/dual_model.html">双模型流水线架构与调优</a></li></ul>`,21)])])}const u=e(s,[["render",r]]);export{g as __pageData,u as default};
